package com.ias.ticket;
import com.ias.trust.*;
import org.junit.jupiter.api.*;
import java.time.Instant;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import static org.junit.jupiter.api.Assertions.*;

class FinanceFreezeCoordinatorTest {
 FinanceQuoteBoundaryTest f;FinanceFreezeCoordinator c;String freeze;AtomicBoolean stockDown;AtomicInteger approvalCalls;
 @BeforeEach void setup()throws Exception{f=new FinanceQuoteBoundaryTest();f.setup();freeze=f.prepare().get("freezeId").toString();stockDown=new AtomicBoolean();approvalCalls=new AtomicInteger();c=new FinanceFreezeCoordinator(f.fixture.tickets,(b,ctx)->{if(!f.sourceAvailable)throw new Problem(404,"OPERATION_NOT_OBSERVED");return new FinanceQuoteBoundary.SourceFact(b,f.sourceState.get(),"COMMITTED".equals(f.sourceState.get())?"c".repeat(64):null);},(owner,action,b,ctx)->{if(owner.equals("stock")&&stockDown.get())throw new Problem(503,"DEPENDENCY_UNAVAILABLE");if(owner.equals("approval"))approvalCalls.incrementAndGet();return receipt(owner,action,b);});}
 Map<String,Object> receipt(String owner,String action,Map<String,Object> b){var out=new LinkedHashMap<>(b);out.put("owner",owner);out.put("state",action.equals("prepare")?"OWNER_FENCED":"OWNER_RELEASED");out.put("ackDigest",FinanceFreezeCoordinator.sha(List.of(owner,action,b)));out.put("coverageDigest","d".repeat(64));out.put("localSnapshot",List.of());out.put("sourceState",f.sourceState.get());out.put("resultDigest",f.sourceState.get().equals("COMMITTED")?"c".repeat(64):null);out.put("checkedAt",Instant.now().toString());return out;}
 FinanceFreezeCoordinator.Context context(){return new FinanceFreezeCoordinator.Context("test",System.currentTimeMillis()+10000);}
 Map<String,Object> advance(){return c.advance(freeze,context());}
 long count(String table){return f.count(table);}
 @Test void onlyTwoPersistedOwnerReceiptsPermitFrozen(){var result=advance();assertEquals("FROZEN",result.get("coordinationState"));assertEquals(true,result.get("globalFreezeAck"));assertEquals(2,count("ticket_finance_owner_ack"));assertEquals(1,count("ticket_finance_coordination_audit"));assertThrows(Problem.class,()->FinanceQuoteBoundary.guard(f.fixture.tickets,f.fixture.ticket));}
 @Test void missingOwnerRetainsFirstReceiptAndRetriesOriginalWithoutDuplicate(){stockDown.set(true);assertThrows(Problem.class,this::advance);assertEquals(1,count("ticket_finance_owner_ack"));assertEquals("FENCING",c.view(c.fence(freeze)).get("coordinationState"));stockDown.set(false);assertEquals(true,advance().get("globalFreezeAck"));assertEquals(1,approvalCalls.get());assertEquals(2,count("ticket_finance_owner_ack"));}
 @Test void source404OrTimeoutNeverReleases(){advance();f.sourceAvailable=false;assertEquals(404,assertThrows(Problem.class,this::advance).status);assertEquals("FROZEN",c.view(c.fence(freeze)).get("coordinationState"));assertThrows(Problem.class,()->FinanceQuoteBoundary.guard(f.fixture.tickets,f.fixture.ticket));}
 @Test void committedReleasesOnlyAfterBothDurableTerminalReceipts(){advance();f.sourceState.set("COMMITTED");stockDown.set(true);assertThrows(Problem.class,this::advance);assertEquals("RECONCILING",c.view(c.fence(freeze)).get("coordinationState"));assertThrows(Problem.class,()->FinanceQuoteBoundary.guard(f.fixture.tickets,f.fixture.ticket));stockDown.set(false);assertEquals("RELEASED",advance().get("coordinationState"));assertEquals(4,count("ticket_finance_owner_ack"));assertDoesNotThrow(()->FinanceQuoteBoundary.guard(f.fixture.tickets,f.fixture.ticket));assertEquals(false,advance().get("globalFreezeAck"));}
 @Test void abortedBeforeOwnerPreparationUsesTerminalReceiptsNeverSyntheticFenceAck(){f.sourceState.set("ABORTED");var result=advance();assertEquals("RELEASED",result.get("coordinationState"));assertNull(result.get("resultDigest"));assertEquals(2,count("ticket_finance_owner_ack"));assertEquals(0,f.fixture.db.queryForObject("SELECT COUNT(*) FROM ticket_finance_owner_ack WHERE phase='FENCED'",Long.class));}
 @Test void alteredReceiptAndIncompleteCoverageCannotAuthorize(){var b=FinanceFreezeCoordinator.wire(c.fence(freeze));var wrong=receipt("approval","prepare",b);wrong.put("actorUserId","999");assertEquals(503,assertThrows(Problem.class,()->c.ownerAck(c.fence(freeze),"approval","FENCED",wrong,new FinanceQuoteBoundary.SourceFact(FinanceQuoteBoundary.binding(c.fence(freeze)),"IN_PROGRESS",null),context())).status);assertEquals(0,count("ticket_finance_owner_ack"));}
 @Test void globalAuditFailureDoesNotPartiallyPublishFrozen(){f.fixture.db.execute("ALTER TABLE ticket_finance_coordination_audit ADD CONSTRAINT qa_global_fail CHECK(event_name<>'FROZEN')");assertThrows(RuntimeException.class,this::advance);assertEquals(2,count("ticket_finance_owner_ack"));assertEquals("FENCING",c.view(c.fence(freeze)).get("coordinationState"));f.fixture.db.execute("ALTER TABLE ticket_finance_coordination_audit DROP CONSTRAINT qa_global_fail");assertEquals("FROZEN",advance().get("coordinationState"));}
 @Test void concurrentRecoveriesKeepOneReceiptPerOwner()throws Exception{try(var pool=Executors.newVirtualThreadPerTaskExecutor()){var gate=new CountDownLatch(1);var calls=new ArrayList<Future<?>>();for(int i=0;i<6;i++)calls.add(pool.submit(()->{gate.await();return advance();}));gate.countDown();for(var call:calls)call.get();}assertEquals(2,count("ticket_finance_owner_ack"));assertEquals("FROZEN",c.view(c.fence(freeze)).get("coordinationState"));}
 @Test void proofIsPureExactAndContainsRealPermitCoverage(){var b=FinanceFreezeCoordinator.wire(c.fence(freeze));long version=f.fixture.version();var fact=c.proof(b,context());assertEquals("IN_PROGRESS",fact.get("sourceState"));assertEquals(List.of(),fact.get("inFlightOperationIds"));assertEquals(version,f.fixture.version());var changed=new LinkedHashMap<>(b);changed.put("companyId","88");assertEquals(409,assertThrows(Problem.class,()->c.proof(changed,context())).status);}
 @Test void cleanupRemainsAvailableWhileNewQuantityAuthorityIsFenced(){advance();assertDoesNotThrow(()->StockExecutionBoundary.guardForPhase(f.fixture.tickets,f.fixture.ticket,"RETURN"));assertDoesNotThrow(()->StockExecutionBoundary.guardForPhase(f.fixture.tickets,f.fixture.ticket,"RELEASE"));for(String action:List.of("RESERVE","ISSUE","USE"))assertEquals("FINANCE_QUOTE_FENCING",assertThrows(Problem.class,()->StockExecutionBoundary.guardForPhase(f.fixture.tickets,f.fixture.ticket,action)).code);}
}
